  "track.arch.kind.complete": "hoàn tất",
  "track.arch.m.god.title": "Một Activity làm mọi thứ, qua bốn phép thử",
  "track.arch.m.god.overview": "Màn Chọn giờ của app Hẹn Khám được viết hai cách: (1) Activity tự gọi mạng, parse JSON, lưu cache và vẽ UI; (2) tách thành UI, ViewModel, repository và nguồn dữ liệu. Cả hai chạy đúng lần đầu. Ta đưa chúng qua bốn phép thử: bấm, xoay màn hình, máy chủ đổi API, viết test.",
  "track.arch.m.god.wrapup": "Kiến trúc không làm app chạy đúng hơn ở lần bấm đầu tiên. Nó quyết định chuyện gì xảy ra sau đó: dữ liệu có sống qua xoay màn hình không, một thay đổi lan ra bao nhiêu file, và có test được trên máy hay phải chạy thiết bị. Nguyên lý gốc là tách mối quan tâm và không giữ dữ liệu trong component mà hệ thống có thể hủy bất cứ lúc nào.",
  "track.arch.m.god.simp.1": "Sơ đồ có bốn tầng cho dễ thấy; hướng dẫn chính thức chỉ yêu cầu tối thiểu UI và data (chương G2). Số file phải sửa là đếm trong app mẫu (ba màn hình cùng gọi API giờ trống).",
  "track.arch.m.god.simp.2": "Hành vi khi xoay màn hình và của ViewModel theo tài liệu chính thức; site không chạy app thật.",
  "track.arch.m.god.ctl.hint": "Đổi cách viết rồi đi lại; so ba số đo ở bước cuối.",
  "track.arch.m.god.ctl.case": "Cách viết",
  "track.arch.m.god.ctl.case.god": "Activity làm mọi thứ",
  "track.arch.m.god.ctl.case.layered": "tách tầng",
  "track.arch.m.god.diagramTitle": "Màn hình, ViewModel, repository, nguồn dữ liệu",
  "track.arch.m.god.diagramDesc": "Một thao tác đi từ màn hình qua state holder và repository tới nguồn dữ liệu; tầng không có thì mờ đi",
  "track.arch.m.god.n.ui": "Màn hình (Activity)",
  "track.arch.m.god.n.vm": "Giữ state (ViewModel)",
  "track.arch.m.god.n.repo": "Repository",
  "track.arch.m.god.n.source": "Nguồn dữ liệu (mạng, DB)",
  "track.arch.m.god.met.keep": "Dữ liệu còn sau khi xoay",
  "track.arch.m.god.met.files": "File phải sửa khi đổi API",
